            return None
        return self.rfile.read(length)

    def parse_json_body(self):
        raw = self.read_body()
        if raw is None:
            self.send_json_error(400, "Missing body")
            return None
        try:
            data = json.loads(raw)
        except (json.JSONDecodeError, ValueError):
            self.send_json_error(400, "Invalid JSON")
            return None
        if not isinstance(data, dict):
            self.send_json_error(400, "JSON body must be an object")
            return None
        return data

    def validate_book(self, data, allow_id=False):
