        parsed = urlparse(self.path)
        path = parsed.path.rstrip('/')  # normalize
        query_params = parse_qs(parsed.query, keep_blank_values=True)

        if path == '/books':
            if self.command == 'GET':
                return self.handle_list_books(query_params)
            elif self.command == 'POST':
                return self.handle_create_book()
        elif path.startswith('/books/'):
            id_str = path[len('/books/'):]
            if not id_str:
                return self.send_json_error(404, "Not found")

            try:
                book_id = int(id_str)
            except ValueError:
                return self.send_json_error(400, "id must be an integer")

            if self.command == 'GET':
                return self.handle_get_book(book_id)
            elif self.command == 'PUT':
                return self.handle_update_book(book_id)
            elif self.command == 'DELETE':
                return self.handle_delete_book(book_id)

        return self.send_json_error(404, "Not found")

    def handle_create_book(self):
        data = self.parse_json_body()
        if data is None:
            return
        valid = self.validate_book(data, allow_id=False)
        if valid is None:
            return

        global next_id
        book_id = next_id
        next_id += 1

        book = {
            'id': book_id,
            'title': data['title'],
            'author': data['author'],
            'isbn': data['isbn'],
            'synopsis': data.get('synopsis', '')
        }
        books[book_id] = book
        self.send_json(201, book)

    def handle_get_book(self, book_id):
        if book_id not in books:
            return self.send_json_error(404, "Book not found")
        self.send_json(200, books[book_id])

    def handle_update_book(self, book_id):
        if book_id not in books:
            return self.send_json_error(404, "Book not found")

        data = self.parse_json_body()
        if data is None:
            return

        valid = self.validate_book(data, allow_id=False)
        if valid is None:
            return

        book = books[book_id]
        book['title'] = data['title']
        book['author'] = data['author']
        book['isbn'] = data['isbn']
        book['synopsis'] = data.get('synopsis', '')

        self.send_json(200, book)

    def handle_delete_book(self, book_id):
        if book_id not in books:
            return self.send_json_error(404, "Book not found")
        del books[book_id]
        self.send_response(204)
        self.send_header('Content-Length', '0')
        self.end_headers()

    def handle_list_books(self, query_params):
        global allowed_query_params
        valid_keys = {'id', 'title', 'author', 'isbn', 'synopsis', 'q'}

        # Check for unknown parameters
        for key in query_params:
            if key not in valid_keys:
                return self.send_json_error(400, f"Unknown query parameter: {key}")

        results = list(books.values())

        # Filter by id (single value)
