            search_val = query_params['q'][0].lower()
            results = [b for b in results if (search_val in b['title'].lower() or 
                                                 search_val in b['author'].lower() or
                                                 search_val in b['isbn'].lower() or
                                                 search_val in b['synopsis'].lower())]

        # Sort by id
        results.sort(key=lambda b: b['id'])
        self.send_json(200, results)

    def do_GET(self):
        self.route()

    def do_POST(self):
        self.route()

    def do_PUT(self):
        self.route()

    def do_DELETE(self):
        self.route()

    # Suppress default logging to stderr (optional, but cleaner)
    def log_message(self, format, *args):
        pass

if __name__ == '__main__':
    port = int(os.environ.get('PORT', 8000))
    server = HTTPServer(('127.0.0.1', port), BookHandler)
    print(f'Serving on http://127.0.0.1:{port}')
    server.serve_forever()
