                          val in b['author'].lower() or
                          val in b['isbn'].lower() or
                          val in b['synopsis'].lower()]
        results.sort(key=lambda b: b['id'])
        self.send_json(200, results)

    def log_message(self, format, *args):
        pass


if __name__ == '__main__':
